import React from 'react';
import {
  Alert,
  Button,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import { Link as RouterLink } from 'react-router-dom';
import ApplicationWarningResolver from './ApplicationWarningResolver';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';

type MeteredBillRemediationStripProps = {
  ocrConfidencePct?: number | null;
  isSpendProxy?: boolean;
  period?: string;
  documentId?: string;
  onResolved?: () => void;
};

const TIER1_OCR_THRESHOLD_PCT = 75;

const MeteredBillRemediationStrip: React.FC<MeteredBillRemediationStripProps> = ({
  ocrConfidencePct,
  isSpendProxy = true,
  period = 'annual',
  documentId,
  onResolved,
}) => {
  const belowTier1Gate = ocrConfidencePct != null && ocrConfidencePct < TIER1_OCR_THRESHOLD_PCT;

  if (!isSpendProxy && !belowTier1Gate) {
    return null;
  }

  return (
    <Alert severity={belowTier1Gate ? 'error' : 'warning'} sx={{ mb: 2 }}>
      <Stack spacing={1}>
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
          <Typography variant="subtitle2" fontWeight={700}>
            Raise readiness with metered data
          </Typography>
          <Chip size="small" color="success" variant="outlined" label="~+12% ISO / Tier 1" />
          {ocrConfidencePct != null ? (
            <Chip size="small" variant="outlined" label={`OCR ${ocrConfidencePct}%`} />
          ) : null}
        </Stack>
        <Typography variant="body2">
          {belowTier1Gate
            ? `OCR quality is below ${TIER1_OCR_THRESHOLD_PCT}% — re-upload a clearer scan or enter activity units manually to unlock carbon and Tier 1 metered uplift.`
            : 'Zoho/Tally imports use ₹ amounts. Upload utility and fuel bills with meter readings to replace spend-proxy estimates.'}
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Button
            size="small"
            variant="contained"
            component={RouterLink}
            to={DOCUMENT_UPLOAD_PATH}
            startIcon={<UploadFileIcon />}
          >
            Upload metered bill
          </Button>
          <Button
            size="small"
            variant="outlined"
            component={RouterLink}
            to="/compliance/india?section=data-sync"
          >
            View Tier 1 progress
          </Button>
          <ApplicationWarningResolver
            compact
            period={period}
            documentId={documentId}
            warnings={[{
              type: belowTier1Gate ? 'ocr_unreadable' : 'spend_proxy_heavy',
              message: 'Add metered kWh, litres, or kg to raise Tier 1 activity share',
            }]}
            onResolved={onResolved}
          />
        </Stack>
      </Stack>
    </Alert>
  );
};

export default MeteredBillRemediationStrip;
